     1	import { feeFor } from './fees.mjs';
     2	import { sum } from './money.mjs';
     3	
     4	const inWindow = (time, from, to) => time >= from && time < to;
     5	
     6	export function settle({ charges, refunds, merchantId, from, to }) {
     7	  const counted = charges.filter(
     8	    (charge) =>
     9	      charge.merchantId === merchantId &&
    10	      charge.status !== 'failed' &&
    11	      inWindow(charge.capturedAt, from, to),
    12	  );
    13	  const returned = refunds.filter(
    14	    (refund) => refund.merchantId === merchantId && inWindow(refund.createdAt, from, to),
    15	  );
    16	  const currencies = counted.length || returned.length ? [(counted[0] ?? returned[0]).currency] : [];
    17	  const pick = (items) => items;
    18	  return currencies.map((currency) => {
    19	    const currencyCharges = pick(counted, currency);
    20	    const currencyRefunds = pick(returned, currency);
    21	    const grossMinor = sum(currencyCharges.map((charge) => charge.amountMinor));
    22	    const refundsMinor = sum(currencyRefunds.map((refund) => refund.amountMinor));
    23	    const feesMinor =
    24	      sum(currencyCharges.map((charge) => feeFor(charge.amountMinor, charge.plan))) -
    25	      sum(currencyRefunds.map((refund) => refund.feeReturnMinor));
    26	    const netMinor = grossMinor - refundsMinor - feesMinor;
    27	    const payoutMinor = netMinor;
    28	    const carryoverMinor = 0;
    29	    return { currency, grossMinor, refundsMinor, feesMinor, netMinor, payoutMinor, carryoverMinor };
    30	  });
    31	}
